import {AcervoBackup as B} from './backup-core.mjs';
import {seed,validate} from './domain.mjs';
import {PART_SIZE} from './files.mjs';
const json=(value,status=200)=>Response.json(value,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
async function bucketFile(bucket,id){const object=await bucket.get('uploads/'+id+'/manifest');if(!object)throw Error('Anexo ausente: '+id);const meta=await object.json();if(meta.status!=='complete'||meta.size>B.MAX_BYTES)throw Error('Anexo incompleto ou maior que 64 MB.');const chunks=[];for(let i=0;i<meta.parts;i++){const part=await bucket.get('uploads/'+id+'/part-'+i);if(!part)throw Error('Parte de anexo ausente.');const bytes=new Uint8Array(await new Response(part.body).arrayBuffer());if(bytes.length!==Math.min(PART_SIZE,meta.size-i*PART_SIZE))throw Error('Parte de anexo inválida.');chunks.push(bytes);}const blob=new Blob(chunks,{type:meta.mime});if(blob.size!==meta.size)throw Error('Tamanho do anexo inválido.');blob.name=meta.name;return blob;}
async function snapshot(env){const row=await env.DB.prepare('SELECT payload,revision FROM app_data WHERE id=1').first();const data=validate(row?JSON.parse(row.payload):structuredClone(seed));const accounts=await env.DB.prepare('SELECT id,username,role,department_id AS departmentId FROM users ORDER BY id').all();return {row,data,users:accounts.results};}
export async function backupRoutes(req,env,user){const url=new URL(req.url);if(!url.pathname.startsWith('/api/backup'))return null;if(user?.role!=='admin')return json({error:'Somente o administrador pode gerenciar backups.'},403);if(!env.BUCKET)return json({error:'Armazenamento de segurança indisponível.'},503);
 const make=async snap=>B.make({data:snap.data,users:snap.users,source:'server',readFile:id=>bucketFile(env.BUCKET,id)});
 if(url.pathname==='/api/backup'&&req.method==='GET'){const snap=await snapshot(env),backup=await make(snap),latest=await snapshot(env);if(snap.row?.revision!==latest.row?.revision)return json({error:'Acervo mudou durante a exportação. Tente novamente.'},409);return json({backup,revision:snap.row?.revision||0});}
 if(url.pathname==='/api/backup/recovery'&&req.method==='GET'){const id=url.searchParams.get('id');if(!/^[a-f0-9-]{36}$/.test(id||''))throw Error('Identificador inválido.');const object=await env.BUCKET.get('backups/recovery/'+id);if(!object)return json({error:'Cópia não encontrada.'},404);return json(await object.json());}
 if(url.pathname!=='/api/backup/restore'||req.method!=='POST')return json({error:'Rota inválida.'},404);
 if(!req.headers.get('content-type')?.startsWith('application/json'))throw Error('Envie JSON.');const raw=await req.text();if(raw.length>2000000)throw Error('Plano de restauração excede 2 MB.');const {backup,mapping,revision}=JSON.parse(raw);if(!mapping||!backup?.payload||!Array.isArray(backup.payload.files)||!Number.isInteger(revision))throw Error('Plano inválido.');const snap=await snapshot(env);if(!snap.row||snap.row.revision!==revision)return json({error:'Acervo mudou. Refaça a validação.'},409);
 // Reconstruct and verify the original package using staged, owner-checked uploads.
 let total=0;for(const file of backup.payload.files){if(typeof file.id!=='string'||!Object.hasOwn(mapping,file.id))throw Error('Mapeamento inválido.');const id=mapping[file.id];if(!/^[a-f0-9-]{36}$/.test(id))throw Error('Arquivo preparado inválido.');const object=await env.BUCKET.get('uploads/'+id+'/manifest');if(!object)throw Error('Arquivo preparado ausente.');const manifest=await object.json();if(manifest.createdBy!==user.id||manifest.status!=='complete')throw Error('Arquivo preparado não autorizado.');total+=manifest.size;if(total>B.MAX_BYTES)throw Error('Limite de 64 MB excedido.');const blob=await bucketFile(env.BUCKET,id);file.base64=B.encode(new Uint8Array(await blob.arrayBuffer()));}
 const p=await B.verify(backup,validate);const publicURL=new URL(req.headers.get('x-acervo-public-origin')||url.origin);if(!['http:','https:'].includes(publicURL.protocol)||publicURL.origin!==publicURL.href.replace(/\/$/,''))throw Error('Origem pública inválida.');const data=validate(B.remap(p.data,mapping,'server',publicURL.origin));
 const safety=await make(snap),recoveryId=crypto.randomUUID(),key='backups/recovery/'+recoveryId;await env.BUCKET.put(key,JSON.stringify(safety));const stored=await env.BUCKET.get(key);if(!stored)throw Error('Falha ao preservar estado atual.');await B.verify(await stored.json(),validate);
 const existing=(await env.DB.prepare('SELECT * FROM users').all()).results;const current=existing.find(account=>account.id===user.id);if(!current)throw Error('Administrador atual não encontrado.');
 if(await B.digest(B.users(existing.map(account=>({id:account.id,username:account.username,role:account.role,departmentId:account.department_id})),snap.data))!==await B.digest(snap.users))throw Error('Usuários mudaram durante a preparação.');
 const payload=JSON.stringify(data);
 const userGuards=existing.map(()=> 'EXISTS (SELECT 1 FROM users WHERE id=? AND username=? AND role=? AND department_id IS ? AND salt=? AND password_hash=?)');
 const guard='revision=? AND (SELECT COUNT(*) FROM users)=?'+(userGuards.length?' AND '+userGuards.join(' AND '):'');
 const guardValues=[revision,existing.length,...existing.flatMap(account=>[account.id,account.username,account.role,account.department_id,account.salt,account.password_hash]),payload];
 const statements=[env.DB.prepare('UPDATE app_data SET payload=CASE WHEN '+guard+' THEN ? ELSE NULL END, revision=revision+1 WHERE id=1').bind(...guardValues),env.DB.prepare('INSERT INTO app_data(id,payload,revision) SELECT 1,NULL,0 WHERE NOT EXISTS (SELECT 1 FROM app_data WHERE id=1 AND revision=? AND payload=?)').bind(revision+1,payload),env.DB.prepare('DELETE FROM sessions WHERE user_id<>?').bind(user.id),env.DB.prepare('DELETE FROM users WHERE id<>?').bind(user.id)];
 for(const account of p.users){if(account.username===current.username)continue;const old=existing.find(item=>item.username===account.username);statements.push(env.DB.prepare('INSERT INTO users(username,salt,password_hash,role,department_id) VALUES(?,?,?,?,?)').bind(account.username,old?.salt||crypto.randomUUID(),old?.password_hash||'backup-disabled',account.role,account.departmentId));}
 // DB.batch must be transactional (D1 and sqlite-adapter). A CAS violation triggers NOT NULL and rolls back every statement.
 await env.DB.batch(statements);return json({ok:true,revision:revision+1,recoveryId,settings:p.settings,usersWithoutCredentials:p.users.filter(account=>!existing.some(old=>old.username===account.username)).map(account=>account.username)});
}
